# /etc/nixos/configuration.nix
{ config, pkgs, lib, ... }:

let
  hostConfig = import ./host-config.nix;
  hostPath = ./hosts/${hostConfig.host};
in
{
  # Sicherheitscheck: Host-Ordner muss existieren
  assertions = [
    {
      assertion = builtins.pathExists hostPath;
      message = "Host '${hostConfig.host}' existiert nicht unter Eco-System/hosts/!";
    }
  ];

  imports = [
    ./modules/init.nix
    # ./default/init.nix   ← ENTFERNT (jetzt profile/base + profile/luis-eco)
    hostPath
    ./modules/finalized.nix
  ];
}

# /etc/nixos/flake.nix
{
  description = "Eco-System NixOS configuration";
  inputs = {
    nixpkgs.url = "github:NixOS/nixpkgs/nixos-26.05";

    # Neuer Input für den unstable-Kanal
    nixpkgs-unstable.url = "github:NixOS/nixpkgs/nixos-unstable";
    # Chaotic Nyx — CachyOS-Kernel mit eigenem, aktiv gepflegtem Cache.
    # Liefert v1 (generic) + thinlto + bore aus dem Cache.
    # Custom-Varianten (v3, zen2, full-lto) werden lokal gebaut
    # via cachyOverride in den jeweiligen Kernel-Modulen.
    chaotic.url = "github:chaotic-cx/nyx/nyxpkgs-unstable";
  };

  # NEU: nixpkgs-unstable in den Argumenten
  outputs = { self, nixpkgs, nixpkgs-unstable, chaotic, ... }:
    let
      system = "x86_64-linux";
      hostConfig = import ./host-config.nix;

      # NEU: Overlay, das pkgs.unstable bereitstellt.
      # Damit kann jedes Modul/Profil gezielt Pakete aus dem
      # unstable-Kanal beziehen (z. B. pkgs.unstable.keepassxc),
      # während das restliche System auf 26.05 bleibt.
      overlay-unstable = final: prev: {
        unstable = import nixpkgs-unstable {
          inherit system;
          config = prev.config;   # allowUnfree etc. erben
        };
      };

      # Nur chaotic wird als extra-Argument an die Module gereicht.
      # Alle kernel/cachyos/*.nix-Dateien erwarten `chaotic`.
      commonArgs = {
        inherit chaotic;
      };
    in
    {
      nixosConfigurations = {
        ${hostConfig.name} = nixpkgs.lib.nixosSystem {
          system = "x86_64-linux";
          modules = [
            # NEU: Overlay laden, bevor configuration.nix greift
            { nixpkgs.overlays = [ overlay-unstable ]; }
            ./configuration.nix
          ];
          specialArgs = commonArgs;
        };

        default = nixpkgs.lib.nixosSystem {
          system = "x86_64-linux";
          modules = [
            # NEU: Overlay laden, bevor configuration.nix greift
            { nixpkgs.overlays = [ overlay-unstable ]; }
            ./configuration.nix
          ];
          specialArgs = commonArgs;
        };
      };
    };
}

# /etc/nixos/host-config.nix
# ==========================================
# SINGLE SOURCE OF TRUTH
# ==========================================
# Diese Datei bestimmt, welcher Host gebaut wird.
# Ändere "name" und "host", um auf einen anderen Host zu wechseln.
# ==========================================

{
  # Der Hostname, den die Flake für nixosConfigurations verwendet
  name = "EXAMPLE";

  # Der Ordner unter Eco-System/hosts/, der importiert wird
  host = "/PATH/TO/HOSTS/INIT/FOLDER";
}

# /etc/nixos/hosts/laptop/init.nix
# ==========================================
# LAPTOP-SPEZIFISCHE KONFIGURATION
# ==========================================
# Dieses Modul enthält alle Einstellungen, die NUR auf dem Laptop gelten.
# Alles, was auch auf dem Desktop gelten soll, gehört nach common/default.nix.
# ==========================================

{ config, pkgs, lib, ... }:

{
  # ==========================================
  # IMPORT
  # ==========================================

  imports = [
    ../../profile/base
    ../../profile/luis-eco

    ./state-version.nix # unfassbar wichtig, nach jeder neuinstalltion von nixos entscheiden ob wert mit updaten
    ./fstab.nix
    ./kernel-modules.nix
    ./wifi-hardware.nix
    ../../modules/userland/nixos_ide.nix
    ../../modules/userland/games/steam.nix
    ../../modules/system/zram-swap.nix
  ];

  #systemd.services.polkit.restartIfChanged          = false;
  #systemd.services.accounts-daemon.restartIfChanged = false;

  # ==========================================
  # HOSTNAME
  # ==========================================
  # Überschreibt den Standard-Hostnamen aus common/default.nix.
  # So erkennst du im Netzwerk, welches Gerät der Laptop ist.
  # ==========================================
  networking.hostName = "Luis-Laptop";

  # ==========================================
  # NIX-BUILD — gezielte Laptop-Overrides
  # ==========================================
  # Aktuell keine Abweichung nötig. Wenn du später einen
  # einzelnen Key überschreiben willst, Punkt-Notation nutzen:
  #
  #   nix.settings.max-jobs = lib.mkForce 2;   # Laptop: nur 2 Jobs
  #   nix.settings.cores    = 0;
  #
  # (kein Block nix.settings = { }; — das würde die Basis-Definition
  #  komplett überschreiben, auch wenn der Block leer wirkt.)
  # ==========================================

  # ==========================================
  # BLUETOOTH
  # ==========================================
  # Nur auf dem Laptop sinnvoll – der Desktop hat meist kein Bluetooth.
  # Experimental = true zeigt den Akkustand von verbundenen Geräten an.
  # FastConnectable reduziert die Verbindungszeit (erhöht aber den Stromverbrauch).
  # AutoEnable schaltet Bluetooth direkt nach dem Booten ein.
  # ==========================================
  hardware.bluetooth = {
    enable      = true;
    powerOnBoot = true;
    settings = {
      General = {
        Experimental    = true;
        FastConnectable = true;
      };
      Policy = {
        AutoEnable = true;
      };
    };
  };


  # ==========================================
  # ZRAM AKTIVIERUNG / RAM KOMPREMIERUNG
  # ==========================================

  mySystem.zramSwap = {
    enable        = true;
    algorithm     = "zstd";    # Der Standard, guter Kompromiss ggfs auf lz4 wechseln
    memoryPercent = 50;        # Maximal 50% des RAMs für zram
    priority      = 100;       # Höher als die SSD-Swap-Priorität (z.B. -1)
  };

  # ==========================================
  # AUTO-LOGIN (nur nach Boot, nicht nach Logout)
  # ==========================================
  # WICHTIG: Wenn du das autologin.nix-Modul verwendest, dann
  # KOMMENTIERE DIE FOLGENDEN ZWEI ZEILEN AUS!
  #
  # Grund: Das autologin.nix-Modul aktiviert den Auto-Login NUR
  # einmalig nach dem Boot. Diese Zeilen hier würden ihn DAUERHAFT
  # aktivieren – auch nach einem manuellen Logout.
  # ==========================================
  # services.displayManager.autoLogin.enable = true;
  # services.displayManager.autoLogin.user   = "luisek03";

  # ==========================================
  # LAPTOP-SPEZIFISCHE PAKETE
  # ==========================================
  # Pakete, die NUR auf dem Laptop installiert werden sollen.
  # (Später z.B. powertop für Energieverwaltung, tlp für Akku-Optimierung)
  #
  # TIPP: Du kannst die Liste der gemeinsamen Pakete aus common/default.nix
  # mit lib.subtractLists oder lib.mkForce anpassen, falls du z.B. Firefox
  # auf dem Laptop nicht haben möchtest.
  # ==========================================
  # flatpak

  services.flatpak.enable = true;
  xdg.portal.enable       = true;


  # ==========================================
  # ENERGIEVERWALTUNG (optional)
  # ==========================================
  # power-profiles-daemon ist der moderne Weg für Energieprofile
  # (powersave, balanced, performance). Viele Laptops brauchen das für
  # eine gute Akkulaufzeit.
  # ==========================================
  # services.power-profiles-daemon.enable = true;

  # ==========================================
  #  WLAN-FIRMWARE (falls nicht in common enthalten)
  # ==========================================
  # Manche Laptops brauchen zusätzliche Firmware für WLAN-Chips.
  # Falls dein WLAN nicht funktioniert, aktiviere diese Zeile:
  # ==========================================
  # hardware.enableRedistributableFirmware = true;


  # ==========================================
  # Laptop-spezifische Eco-Update-Einstellungen
  # ==========================================

  #mySystem.autoGC = {   # wird vermutlich entfernt
  #  maxUsed = 85;          # Laptop hat weniger Speicher
  #  deleteOlderThan = "14d"; # Laptop braucht weniger alte Generationen
  #};

  mySystem.ops.update = {
    enable     = true;
    retries    = 0;
    retryDelay = 10;

    cacheCheck = {
      enable = true;
      # input und caches erben vom Default
    };

    flakeLockBackup = {
      enable     = true;
      autoCommit = true;
    };

    # Post-Update-Hook: Shell-String, wird per bash -c ausgeführt
    postUpdate = {
      enable = true;
      script = "eco-gc-retention";
    };
  };

  # Teil 1: Retention — nur Binary bereitstellen
  mySystem.ops.gc.retention = {
    enable               = true;
    keepDays             = 7;
    minGenerations       = 4;
    safetyHours          = 24;
    maxSafetyGenerations = 20;
  };

    # Teil 2: Collect — Binary + Timer
  mySystem.ops.gc.collect = {
    enable       = true;
    startPercent = 85;
    targetPercent = 80;
    #maxIterations = 3;
    #checkPath = "/nix/store"; ist bereits default
    #schedule = "daily";   # "daily" / "weekly" / "never"
    #schedule erbt jz von ops/common.nix default daily
  };



  # ==========================================
  # IDE AKTIVIEREN (Bool)
  # ==========================================
  mySystem.ide = {
    enable   = true;   # <-- auf false setzen, um IDE zu deaktivieren
    repoUrl  = "git@github.com:luisek03/Eco-System.git";
    repoPath = "/home/luisek03/Projekte/Eco-System";
    userName = "luisek03";
  };

  # ==========================================
  # Aktivierung von steam und andere games launcher
  # ==========================================

  mySystem.steam.enable = true;

}

# /etc/nixos/Eco-System/hosts/laptop/fstab.nix
{ config, lib, pkgs, modulesPath, ... }:

{
  # ==========================================
  # IMPORT: Hardware-Erkennung
  # ==========================================
  imports = [
    (modulesPath + "/installer/scan/not-detected.nix")
  ];

  # ==========================================
  # LUKS-VERSCHLÜSSELUNG (Hauptpartition)
  # ==========================================
  boot.initrd.luks.devices."luks-8f434902-3496-446b-908f-e0f4010a434b" = {
    device = "/dev/disk/by-uuid/8f434902-3496-446b-908f-e0f4010a434b";
  };

  # ==========================================
  # LUKS-VERSCHLÜSSELUNG (SWAP-Partition – separat!)
  # ==========================================
  boot.initrd.luks.devices."luks-70b818df-e3e5-401c-99fd-41188984daa4" = {
    device = "/dev/disk/by-uuid/70b818df-e3e5-401c-99fd-41188984daa4";
  };

  # ==========================================
  # FILESYSTEMS (Mounts)
  # ==========================================
  fileSystems = {
    "/" = {
      device  = "/dev/mapper/luks-8f434902-3496-446b-908f-e0f4010a434b";
      fsType  = "btrfs";
      options = [ "compress=zstd:1" ];
    };

    "/home" = {
      device  = "/dev/mapper/luks-8f434902-3496-446b-908f-e0f4010a434b";
      fsType  = "btrfs";
      options = [ "subvol=home" "compress=zstd:1" ];
    };

    "/nix" = {
      device  = "/dev/mapper/luks-8f434902-3496-446b-908f-e0f4010a434b";
      fsType  = "btrfs";
      options = [ "subvol=nix" "compress=zstd:1" "noatime" ];
    };

    "/boot" = {
      device  = "/dev/disk/by-uuid/E762-C728";
      fsType  = "vfat";
      options = [ "fmask=0077" "dmask=0077" ];
    };
  };

  # ==========================================
  # SWAP (separate verschlüsselte Partition)
  # ==========================================
  swapDevices = [
    { device = "/dev/mapper/luks-70b818df-e3e5-401c-99fd-41188984daa4"; }
  ];
}

# /etc/nixos/Eco-System/modules/finalized.nix
{ config, pkgs, lib, ... }:

{
  # ==========================================
  # (Optional) WEITERE SYSTEMWEITE PAKETE
  # ==========================================
  # Hier kannst du Pakete hinzufügen, die auf ALLEN Hosts
  # installiert sein sollen, aber nicht in default/init.nix stehen.
  # ==========================================
  # environment.systemPackages = with pkgs; [
  #   # ...
  # ];

  nix.settings = {
    extra-substituters        = config.mySystem.caches.substituters;
    extra-trusted-public-keys = config.mySystem.caches.trustedKeys;
  };
}

# /etc/nixos/Eco-System/modules/init.nix
# ==========================================
# SYSTEMRELEVANTE OPTIONS
# ==========================================
# Nur Options, die tatsächlich zwischen Modulen wandern.
# Alle anderen Werte (Locale, Zeitzone, Tastatur) stehen direkt
# in default/init.nix – sie werden von keinem Modul gelesen.
# ==========================================

{ config, pkgs, lib, ... }:

{
  options.mySystem = {
    # ==========================================
    # BENUTZER
    # ==========================================
    # userName wird gelesen von:
    #   - modules/system/ops/common.nix (git author email)
    #   - modules/system/ops/update.nix (--user Argument)
    #   - modules/init.nix selbst (paths.repo Default)
    #
    # userFullName wird gelesen von:
    #   - modules/system/ops/common.nix (git author name)
    #
    # Wichtig: Auch users.users.<name> und SSH-Keys sollten diesen
    # Wert nutzen, nicht das Literal "luisek03". Sonst ist der Name
    # doppelt gepflegt.
    # ==========================================
    userName = lib.mkOption {
      type = lib.types.str;
      default = "luisek03";
      description = ''
        Primärer Benutzername.
        Wird für Git-Commits, eco-update und Benutzer-Deklaration genutzt.
      '';
    };

    userFullName = lib.mkOption {
      type = lib.types.str;
      default = "Luis Fernando Meyer";
      description = ''
        Voller Name des Benutzers.
        Wird als Git-Autor-Name und Beschreibung in users.users genutzt.
      '';
    };

    # ==========================================
    # PFADE
    # ==========================================
    # paths.repo ist die Schnittstelle zwischen Modulen und
    # Repo-Struktur. Es wird gelesen von:
    #   - modules/system/ops/common.nix (flakeLockBackup.repoPath)
    #   - modules/userland/nixos_ide.nix (eco-Aliase, deploy-Aliase)
    #   - zukünftigen Deploy-Skripten und eco-update-Hooks
    #
    # Der Wert ist pro Nutzer unterschiedlich. Profile können ihn
    # überschreiben (z. B. profile/<user>/default.nix mit mkForce).
    # ==========================================
    paths = {
      repo = lib.mkOption {
        type = lib.types.str;
        default = "/home/${config.mySystem.userName}/Projekte/Eco-System";
        description = ''
          Pfad zum Git-Repo des Nutzers.

          Wird von eco-update, IDE-Aliasen und Deploy-Skripten genutzt.
          Kann pro Profil überschrieben werden (siehe profile/<user>).

          Das Repo muss nicht auf einem Server liegen – ein lokales
          Git-Repository reicht. Es dient der Versionskontrolle der
          eigenen Konfiguration.
        '';
      };
    };
  };


  options.mySystem.caches = {
    substituters = lib.mkOption {
      type = lib.types.listOf lib.types.str;
      default = [];
      description = ''
        Zusätzliche Substituter, die Module beitragen.
        Werden von finalized.nix in nix.settings.extra-substituters aufgelöst.
        Alle Beiträge werden gemergt (types.listOf, gleiche Priorität).
      '';
    };

    trustedKeys = lib.mkOption {
      type = lib.types.listOf lib.types.str;
      default = [];
      description = ''
        Trusted Public Keys zu den Substitutern.
        Werden von finalized.nix in nix.settings.extra-trusted-public-keys aufgelöst.
      '';
    };
  };
}

{ lib, ... }:
{
  options.mySystem.customKernel = {
    enable = lib.mkOption {
      type = lib.types.bool;
      default = false;
      description = ''
        Aktiviert den importierten Kernel.

        Wenn false und kernel/default.nix importiert wurde, greift
        der NixOS-LTS-Kernel als Fallback.

        Wenn true, setzt die importierte Kernel-Datei (chaotic,
        lto-v3, lto-zen) den `boot.kernelPackages`. Importiere
        immer nur eine Kernel-Datei, sonst kollidieren die
        Zuweisungen.
      '';
    };

    lts = lib.mkOption {
      type = lib.types.bool;
      default = false;
      description = ''
        Wird NUR von chaotic.nix ausgewertet. Alle anderen
        Kernel-Dateien (lto-v3, lto-zen) ignorieren diese Option,
        weil sie immer gegen einen festen CachyOS-Base bauen.
      '';
    };
  };
}

# modules/system/kernel/cachyos/chaotic.nix
{ config, pkgs, lib, chaotic, ... }:
let
  cfg = config.mySystem.customKernel;

  chaoticPkgs = import chaotic.inputs.nixpkgs {
    inherit (pkgs.stdenv.hostPlatform) system;
    # config = pkgs.config;    ← weglassen, für Cache-Hit
    overlays = [ chaotic.overlays.default ];
  };

  cachyos = if cfg.lts
            then chaoticPkgs.linuxPackages_cachyos-lts
            else chaoticPkgs.linuxPackages_cachyos-lto;
in
{
  imports = [ ./common.nix ];

  config = lib.mkIf cfg.enable {
    # Cache — als Beitrag zur mySystem.caches-Option
    # Selbst wenn base den nyx-cache schon hat: dieses Modul ist autark.
    # Nix dedupliziert beim Schreiben von nix.conf.
    mySystem.caches.substituters = [ "https://nyx-cache.chaotic.cx" ];
    mySystem.caches.trustedKeys  = [ "nyx-cache.chaotic.cx:dJxTrgMC3V3cFfyIiBQDQorG6k1LsqurH/srpMSq7qk=" ];

    mySystem.ops.update.cacheCheck.caches = [ "https://nyx-cache.chaotic.cx" ];

    boot.kernelPackages = cachyos;
    boot.kernel.sysctl."kernel.sched_bore" = 1;
  };
}

{ ... }:
{
  # Zieht die Options UND den LTS-Fallback rein.
  # Alle CachyOS-Kernel-Dateien importieren diese eine Zeile,
  # statt den Host mit zwei Imports zu belasten.
  imports = [ ../default.nix ];
}

{ ... }:
{
  imports = [
    ./chaotic.nix
  ];
}

# modules/system/kernel/cachyos/lto-v3.nix
{ config, pkgs, lib, chaotic, ... }:
let
  cfg = config.mySystem.customKernel;

  # Eigene pkgs-Instanz aus chaotic's nixpkgs.
  # Diese Instanz ist IDENTISCH mit dem, was chaotic zum Bauen nutzt
  # → gleicher Hash → Cache-Hit.
  chaoticPkgs = import chaotic.inputs.nixpkgs {
    inherit (pkgs.stdenv.hostPlatform) system;
    # config = pkgs.config;    ← weglassen
    overlays = [ chaotic.overlays.default ];
  };

  base = chaoticPkgs.linuxPackages_cachyos-lto;
in
{
  imports = [ ./common.nix ];

  config = lib.mkIf cfg.enable {
    # lto-v3 hat keinen eigenen Cache (wird immer lokal gebaut),
    # aber die nyx-cache-Substituter bleiben für die Abhängigkeiten
    # des Kernels (kmod, linux-firmware, …) relevant.
    mySystem.caches.substituters = [ "https://nyx-cache.chaotic.cx" ];
    mySystem.caches.trustedKeys  = [ "nyx-cache.chaotic.cx:dJxTrgMC3V3cFfyIiBQDQorG6k1LsqurH/srpMSq7qk=" ];

    boot.kernelPackages = base.cachyOverride {
      cachyVars = base.kernel.cachyConfig.cachyVars // {
        "_processor_opt" = "GENERIC_V3";
        "_use_llvm_lto" = "thin";
      };
    };

    boot.kernel.sysctl."kernel.sched_bore" = 1;
  };
}

{ ... }:
{
  imports = [
    ./_options.nix
    ./lts.nix
  ];
}

# modules/system/kernel/lts.nix
{ config, pkgs, lib, ... }:
{
  imports = [ ./_options.nix ];

  config = lib.mkIf (!config.mySystem.customKernel.enable) {
    # NixOS-Standard-Kernel = neuester LTS.
    # Wenn kein Custom-Kernel aktiv ist, greift dieser Fallback.
    boot.kernelPackages = pkgs.linuxPackages;
  };
}

# modules/system/ops/common.nix
{ config, lib, ... }:

{
  options.mySystem.ops = {
    update = {
      enable = lib.mkOption {
        type = lib.types.bool;
        default = false;
      };

      retries = lib.mkOption {
        type = lib.types.int;
        default = 0;
        description = "Max retries per step (0 = infinite).";
      };

      retryDelay = lib.mkOption {
        type = lib.types.int;
        default = 10;
      };

      cacheCheck = {
        enable = lib.mkOption {
          type = lib.types.bool;
          default = true;
          description = ''
            Cache-Check vor Kernel-Update aktivieren.
            Prüft, ob der aktive Kernel in den angegebenen Caches liegt.
          '';
        };

        # Wird vom aktiven Kernel-Modul gesetzt (z. B. chaotic.nix).
        # Leer bedeutet: kein Cache wird geprüft, der Check wird
        # übersprungen. Nur Kernel-Module, die tatsächlich einen
        # Cache haben, setzen hier etwas.
        caches = lib.mkOption {
          type = lib.types.listOf lib.types.str;
          default = [];
          description = ''
            Caches, in denen der aktive Kernel gesucht wird.
            Wird vom jeweiligen Kernel-Modul gesetzt.
          '';
        };
      };

      flakeLockBackup = {
        enable = lib.mkOption { type = lib.types.bool; default = false; };
        repoPath = lib.mkOption {
          type = lib.types.str;
          default = config.mySystem.paths.repo;
          defaultText = lib.literalExpression "config.mySystem.paths.repo";
        };
        autoCommit = lib.mkOption { type = lib.types.bool; default = false; };
        commitMessage = lib.mkOption {
          type = lib.types.str;
          default = "eco-update: flake.lock für %HOST% (%DATE%)";
        };
        gitAuthorName = lib.mkOption {
          type = lib.types.str;
          default = config.mySystem.userFullName;
        };
        gitAuthorEmail = lib.mkOption {
          type = lib.types.str;
          default = "${config.mySystem.userName}@localhost";
        };
      };

      # Post-Update-Hook: Shell-String, wird per bash -c ausgeführt.
      # Kann mehrere Befehle enthalten (&&, ;, |).
      postUpdate = {
        enable = lib.mkOption { type = lib.types.bool; default = false; };
        script = lib.mkOption {
          type = lib.types.nullOr lib.types.str;
          default = null;
          description = ''
            Shell-Befehl nach erfolgreichem switch.
            Beispiel: "eco-gc-retention"
            Beispiel: "eco-gc-retention && notify-send 'GC done'"
          '';
        };
      };
    };

    gc = {
      # ------------------------------------------------------------------
      # Teil 1: Retention
      # ------------------------------------------------------------------
      # Stellt nur das Binary `eco-gc-retention` bereit.
      # Kein systemd-Service, keine Path-Unit.
      # Wird typischerweise als postUpdate-Hook von eco-update aufgerufen.
      retention = {
        enable = lib.mkOption {
          type = lib.types.bool;
          default = false;
          description = ''
            Stellt eco-gc-retention bereit.
            Wird normalerweise per mySystem.ops.update.postUpdate.script
            als Hook aufgerufen.
          '';
        };

        keepDays = lib.mkOption {
          type = lib.types.int;
          default = 7;
        };

        minGenerations = lib.mkOption {
          type = lib.types.int;
          default = 4;
        };

        safetyHours = lib.mkOption {
          type = lib.types.int;
          default = 24;
          description = ''
            Generationen der letzten N Stunden werden immer behalten,
            unabhängig von Kalendertagen.

            Schützt späte Abend-Builds davor, nach Mitternacht aus dem
            Keep-Day-Fenster zu fallen. Setze 0, um die Regel zu deaktivieren
            (dann greift nur noch keepDays).
          '';
        };

        maxSafetyGenerations = lib.mkOption {
          type = lib.types.int;
          default = 20;
          description = ''
            Obergrenze für Generationen aus dem Safety-Fenster.

            Nach dem Safety-Filter werden nur die N neuesten Generationen
            behalten. Der Rest fällt aus dem Safety-Set, kann aber durch
            andere Regeln (rule_current, rule_keep_day, rule_floor)
            weiterhin geschützt sein.

            Sinn: Verhindert, dass ein einziger Deploy-Tag mit vielen
            Builds den Bootloader flutet. Der Wert sollte so gewählt sein,
            dass er selten erreicht wird — sonst greift der Cap ständig.

            Setze 0, um den Cap zu deaktivieren (unbegrenzt).
          '';
        };
      };

      # ------------------------------------------------------------------
      # Teil 2: Collect
      # ------------------------------------------------------------------
      # Stellt Binary `eco-gc-collect` + systemd-Service + systemd-Timer
      # bereit. Der Service entscheidet selbst, ob Speicher voll genug ist.
      # Kein Path-Unit, kein Rebuild-Trigger.
      collect = {
        enable = lib.mkOption {
          type = lib.types.bool;
          default = false;
        };

        startPercent = lib.mkOption {
          type = lib.types.int;
          default = 85;
          description = "Ab dieser Auslastung wird GC gestartet.";
        };

        targetPercent = lib.mkOption {
          type = lib.types.int;
          default = 80;
          description = "Bis zu dieser Auslastung wird GC laufen gelassen.";
        };

        maxIterations = lib.mkOption {
          type = lib.types.int;
          default = 3;
          description = ''
            Maximale GC-Läufe hintereinander. Danach wird abgebrochen,
            auch wenn target nicht erreicht (Speicher könnte durch
            andere Dinge voll sein).
          '';
        };

        checkPath = lib.mkOption {
          type = lib.types.str;
          default = "/nix/store";
          description = "Pfad, dessen Partition geprüft wird.";
        };

        schedule = lib.mkOption {
          type = lib.types.enum [ "daily" "weekly" "never" ];
          default = "daily";
          description = ''
            systemd-Timer-Intervall.
            "never" deaktiviert den Timer — Collect läuft dann nur manuell.
          '';
        };
      };
    };
  };
}

