# modules/system/ops/gc.nix
{ config, pkgs, lib, ... }:

let
  retentionCfg = config.mySystem.ops.gc.retention;
  collectCfg = config.mySystem.ops.gc.collect;

  # ------------------------------------------------------------------
  # Binary: eco-gc-retention
  # ------------------------------------------------------------------
  ecoGcRetention = pkgs.writeShellApplication {
    name = "eco-gc-retention";
    runtimeInputs = with pkgs; [ python3 nix e2fsprogs ];
    text = ''
      exec python3 ${./gc-retention.py} \
        --keep-days ${toString retentionCfg.keepDays} \
        --min-generations ${toString retentionCfg.minGenerations} \
        --safety-hours ${toString retentionCfg.safetyHours} \
        --max-safety-generations ${toString retentionCfg.maxSafetyGenerations} \
        "$@"
    '';
  };

  # ------------------------------------------------------------------
  # Binary: eco-gc-collect
  # ------------------------------------------------------------------
  ecoGcCollect = pkgs.writeShellApplication {
    name = "eco-gc-collect";
    runtimeInputs = with pkgs; [ python3 nix coreutils ];
    text = ''
      exec python3 ${./gc-collect.py} \
        --start-percent ${toString collectCfg.startPercent} \
        --target-percent ${toString collectCfg.targetPercent} \
        --max-iterations ${toString collectCfg.maxIterations} \
        --path ${lib.escapeShellArg collectCfg.checkPath} \
        "$@"
    '';
  };

  scheduleMap = {
    daily  = "daily";
    weekly = "weekly";
  };

in
{
  config = lib.mkMerge [
    # ------------------------------------------------------------------
    # Retention: nur Binary, kein Service
    # ------------------------------------------------------------------
    (lib.mkIf retentionCfg.enable {
      environment.systemPackages = [ ecoGcRetention ];
    })

    # ------------------------------------------------------------------
    # Collect: Binary + Service + Timer
    # ------------------------------------------------------------------
    (lib.mkIf collectCfg.enable {
      environment.systemPackages = [ ecoGcCollect ];

      systemd.services.eco-gc-collect = {
        description = "eco-gc-collect — Nix-Store aufräumen bei Platzmangel";
        serviceConfig = {
          Type = "oneshot";
          Nice = 19;
          IOSchedulingClass = "idle";
          ExecStart = "${ecoGcCollect}/bin/eco-gc-collect";
          # Exit-Codes des Skripts:
          #   0 — Ziel erreicht oder nichts zu tun
          #   1 — echter Fehler (GC fehlgeschlagen)
          #   2 — Validierungsfehler
          #   3 — Ziel nicht erreicht, kein Fehler
          # Für systemd sind 0 und 3 erfolgreich. Fehler (1, 2) bleiben
          # sichtbar in `systemctl --failed`.
          SuccessExitStatus = "0 3";
        };
      };

      systemd.timers.eco-gc-collect = lib.mkIf (collectCfg.schedule != "never") {
        description = "Periodischer eco-gc-collect-Lauf";
        wantedBy = [ "timers.target" ];
        timerConfig = {
          OnCalendar = scheduleMap.${collectCfg.schedule};
          Persistent = true;
          RandomizedDelaySec = "1h";
          Unit = "eco-gc-collect.service";
        };
      };
    })
  ];
}

# modules/system/ops/update.nix
{ config, pkgs, lib, ... }:

let
  cfg = config.mySystem.ops.update;
  backup = cfg.flakeLockBackup;
  hook = cfg.postUpdate;

  # --cache-urls nur setzen, wenn Caches konfiguriert sind.
  # Sonst bricht argparse ab („expected one argument").
  cacheUrlsArg =
    lib.optionalString (cfg.cacheCheck.caches != [])
      "--cache-urls ${lib.concatStringsSep "," cfg.cacheCheck.caches}";

  ecoUpdate = pkgs.writeShellApplication {
    name = "eco-update";
    runtimeInputs = with pkgs; [ python3 nix git curl coreutils nix-output-monitor ];
    text = ''
      exec python3 ${./update} \
        --user ${config.mySystem.userName} \
        --retries ${toString cfg.retries} \
        --delay ${toString cfg.retryDelay} \
        --cache-check ${if cfg.cacheCheck.enable then "1" else "0"} \
        ${cacheUrlsArg} \
        --backup ${if backup.enable then "1" else "0"} \
        --backup-repo ${backup.repoPath} \
        --backup-commit ${if backup.autoCommit then "1" else "0"} \
        --backup-msg ${lib.escapeShellArg backup.commitMessage} \
        --git-author-name ${lib.escapeShellArg backup.gitAuthorName} \
        --git-author-email ${lib.escapeShellArg backup.gitAuthorEmail} \
        --hook ${if hook.enable then "1" else "0"} \
        --hook-script ${lib.escapeShellArg (hook.script or "")} \
        "$@"
    '';
  };
in
{
  config = lib.mkIf cfg.enable {
    environment.systemPackages = [ ecoUpdate ];
  };
}

#!/usr/bin/env python3
"""
Cache-Prüfung für eco-update: Store-Pfad-Eval, Verify, Pin-Check.
"""

import os
import subprocess
from pathlib import Path

from manifest import (
    CachePinError,
    load_file,
    merge,
    parse_line,
    resolve_expr,
)


FLAKE = "/etc/nixos"
HOST_CONFIG = "/etc/nixos/host-config.nix"

KERNEL_EXPR = (
    "nixosConfigurations.default.config."
    "boot.kernelPackages.kernel.outPath"
)


# ----------------------------------------------------------------------
# Store-Pfad-Auflösung
# ----------------------------------------------------------------------

def eval_store_path(expr):
    """Evaluiert einen Nix-Ausdruck relativ zur Flake zu einem Store-Pfad."""
    try:
        out = subprocess.check_output(
            ["nix", "eval", "--raw", f"{FLAKE}#{expr}"],
            stderr=subprocess.PIPE, text=True, timeout=300,
        )
        return out.strip()
    except subprocess.CalledProcessError as e:
        err = (e.stderr or "").strip()
        print(f"⚠️  Evaluation von '{expr}' fehlgeschlagen (rc={e.returncode}).")
        if err:
            lines = err.splitlines()
            for line in (lines[-20:] if len(lines) > 20 else lines):
                print(f"    {line}")
        return None
    except subprocess.TimeoutExpired:
        print(f"⚠️  Evaluation von '{expr}': Timeout nach 300 s.")
        return None
    except FileNotFoundError:
        print("⚠️  'nix' nicht im PATH gefunden.")
        return None


def cache_has_path(store_path, urls):
    """Prüft, ob der Pfad in einem der Caches mit gültiger Signatur liegt."""
    if not store_path or not store_path.startswith("/nix/store/"):
        return False
    for url in urls:
        try:
            r = subprocess.run(
                ["nix", "store", "verify",
                 "--store", url, "--sigs-needed", "1", store_path],
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL, timeout=30,
            )
            if r.returncode == 0:
                return True
        except Exception:
            continue
    return False


# ----------------------------------------------------------------------
# Manifest-Laden aus festen Pfaden
# ----------------------------------------------------------------------

def _read_host():
    import re
    try:
        m = re.search(r'\bhost\s*=\s*"([^"]+)"',
                      Path(HOST_CONFIG).read_text())
        return m.group(1) if m else None
    except FileNotFoundError:
        return None


def collect_pins(user_pins):
    """
    Sammelt alle Pins.
    Reihenfolge: Kernel → default → host → user_pins.
    Kernel ist fix und kann nicht überschrieben werden.

    user_pins: Liste von Strings (Manifest-Zeilen oder Include-Pfade).
    Rückgabe: dict[name] = {"expr": ..., "params": {...}}
    """

    pins = {}
    seen = set()

    # Kernel — fix
    pins["kernel"] = {
        "expr": KERNEL_EXPR,
        "params": {"pin-on-cache": "true"},
    }

    entry_lists = []

    # Host-Manifest
    host = _read_host()
    if host:
        host_path = Path(FLAKE) / "hosts" / host / "cache-manifest" / "init.chp"
        if host_path.is_file():
            entries = load_file(host_path, seen)
            entry_lists.append(entries)
            print(f"📄 Host-Manifest: {host_path} ({len(entries)} Einträge)")

    # User-Pins
    if user_pins:
        entries = []
        for i, arg in enumerate(user_pins):
            kind, payload = parse_line(arg, source=f"--cache-pin[{i}]")
            if kind == "empty":
                continue
            if kind == "include":
                p = Path(payload)
                if not p.is_absolute():
                    p = Path.cwd() / p
                entries.extend(load_file(p, seen))
            elif kind == "package":
                entries.append(payload)
        entry_lists.append(entries)
        print(f"📄 --cache-pin: {len(entries)} Einträge")

    manifests = merge(entry_lists)
    for name, params in manifests.items():
        if name == "kernel":
            print("⚠️  Manifest-Eintrag 'kernel' ignoriert.")
            continue
        pins[name] = {
            "expr": resolve_expr(name),
            "params": params,
        }

    return pins


def check_all_pins(user_pins, urls):
    """
    Prüft alle Pins mit pin-on-cache=true.
    Rückgabe: True wenn alle im Cache, sonst False.
    """
    pins = collect_pins(user_pins)
    total = len(pins)
    all_ok = True
    checked = 0
    skipped = 0

    for name, info in pins.items():
        params = info["params"]
        if params.get("pin-on-cache", "true") != "true":
            print(f"⏭️  {name}: pin-on-cache=false — ignoriert.")
            skipped += 1
            continue

        expr = info["expr"]
        if expr.startswith("/nix/store/"):
            path = expr
        else:
            path = eval_store_path(expr)

        if not path:
            print(f"❌ {name}: Store-Pfad nicht ermittelbar.")
            all_ok = False
            continue

        checked += 1
        if cache_has_path(path, urls):
            print(f"✅ {name} im Cache.")
        else:
            print(f"❌ {name} nicht im Cache.")
            all_ok = False

    print(f"\n📊 {total} Pins gesamt, {checked} geprüft, "
          f"{skipped} übersprungen.")
    return all_ok

#!/usr/bin/env python3
"""Asynchroner Check: Läuft der aktuelle stabile NixOS-Kanal noch?

Startet einen Hintergrund-Thread, der die Prometheus-API von NixOS
abfragt. Das Future wird erst vor dem Post-Hook ausgewertet — bis
dahin sind flake update / build / switch längst durch, also kein
zusätzlicher Zeitverlust.
"""

import json
import re
import sys
import urllib.request
from concurrent.futures import ThreadPoolExecutor, TimeoutError as FutureTimeout
from pathlib import Path

from colors import Color


FLAKE_NIX     = "/etc/nixos/flake.nix"
PROMETHEUS_URL = "https://prometheus.nixos.org/api/v1/query?query=channel_revision"
CHANNEL_RE    = re.compile(r'nixpkgs\.url\s*=\s*"github:NixOS/nixpkgs/(nixos-\d{2}\.\d{2})"')
STABLE_RE     = re.compile(r"^nixos-\d{2}\.\d{2}$")
TIMEOUT_SECONDS = 15

_executor = None


def _read_current_channel():
    try:
        content = Path(FLAKE_NIX).read_text()
    except OSError:
        return None
    m = CHANNEL_RE.search(content)
    return m.group(1) if m else None


def _fetch_latest_stable():
    req = urllib.request.Request(
        PROMETHEUS_URL,
        headers={"User-Agent": "eco-update/1.0"},
    )
    with urllib.request.urlopen(req, timeout=TIMEOUT_SECONDS) as resp:
        data = json.loads(resp.read().decode())
    channels = [
        r["metric"]["channel"]
        for r in data["data"]["result"]
        if "channel" in r["metric"]
    ]
    stable = sorted(c for c in channels if STABLE_RE.match(c))
    if not stable:
        raise RuntimeError("Keine stabilen Kanaele in der API-Antwort.")
    return stable[-1]


def _check():
    current = _read_current_channel()
    if current is None:
        return ("error", "Konnte aktuellen Kanal nicht aus flake.nix lesen.")
    try:
        latest = _fetch_latest_stable()
    except Exception as e:
        return ("error", f"API-Check fehlgeschlagen: {e}")
    return ("ok", current, latest)


def start_channel_check():
    """Startet den Check im Hintergrund. Rueckgabe: Future."""
    global _executor
    _executor = ThreadPoolExecutor(max_workers=1)
    return _executor.submit(_check)


def _shutdown_executor():
    if _executor is not None:
        _executor.shutdown(wait=False, cancel_futures=True)


def evaluate_channel_check(future):
    """Wertet das Future aus und gibt die farbliche Meldung aus."""
    c = Color(no_color=not sys.stdout.isatty())
    try:
        try:
            result = future.result(timeout=TIMEOUT_SECONDS)
        except FutureTimeout:
            print(c.yellow(
                "⚠️  Kanal-Check: Timeout — konnte nicht abgeschlossen werden."
            ))
            return
        except Exception as e:
            print(c.red(f"❌ Kanal-Check fehlgeschlagen: {e}"))
            return

        if result[0] == "error":
            print(c.red(f"❌ Kanal-Check: {result[1]}"))
            return

        _, current, latest = result
        if current == latest:
            print(c.green(f"✅ Stabiler Kanal aktuell: {current}"))
        else:
            print(c.yellow(
                f"⚠️  Kanal-Update verfuegbar: {current} → {latest}\n"
                f"   In flake.nix anpassen:\n"
                f"   nixpkgs.url = \"github:NixOS/nixpkgs/{latest}\";"
            ))
    finally:
        _shutdown_executor()

#!/usr/bin/env python3
"""Lock-Handling für eco-update und eco-gc-retention."""

import fcntl
from pathlib import Path


LOCKFILE = "/run/lock/eco-update.lock"
HOOK_ENV_VAR = "ECO_UPDATE_HOLDING_LOCK"


def acquire_lock():
    """Erwirbt den Lock. Rückgabe: file object oder None."""
    try:
        Path("/run/lock").mkdir(exist_ok=True)
        fd = open(LOCKFILE, "w")
        fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
        return fd
    except BlockingIOError:
        return None
    except Exception:
        return None


def release_lock(fd):
    """Gibt den Lock frei. Kein unlink — flock arbeitet auf Inodes."""
    if fd is not None:
        try:
            fcntl.flock(fd, fcntl.LOCK_UN)
            fd.close()
        except Exception:
            pass


def hook_is_holding_lock() -> bool:
    """True, wenn wir als Post-Update-Hook laufen (Parent hält Lock)."""
    import os
    return os.environ.get(HOOK_ENV_VAR) == "1"

#!/usr/bin/env python3
"""
Manifest-Parser und Pin-Merge für eco-update.

Format (.chp):
  # Kommentar
  firefox
  chromium:pin-on-cache=true
  thunderbird:{pin-on-cache=true; note="mail"}
  include /pfad/zu/anderer.chp
  nixosConfigurations.default.pkgs.blender.outPath

Regeln:
  - Letzter Eintrag gewinnt (innerhalb Datei und über Ebenen hinweg).
  - include expandiert inline (rekursiv).
  - Dieselbe absolute Datei darf nur einmal vorkommen → Fehler.
"""

import re
from pathlib import Path


PARAM_DEFAULTS = {
    "pin-on-cache": "true",
}


class CachePinError(Exception):
    """Fehler beim Parsen oder Auswerten von Cache-Manifesten."""
    pass


def parse_line(line, source="<arg>"):
    """
    Parst eine Zeile.
    Rückgabe: ("empty", None) | ("include", pfad) | ("package", (name, params))
    """
    line = line.strip()
    if not line or line.startswith("#"):
        return ("empty", None)

    if line == "include" or line.startswith("include "):
        path = line[len("include"):].strip()
        if not path:
            raise CachePinError(f"{source}: 'include' ohne Pfad")
        return ("include", path)

    name = line
    params = {}

    if ":" in line:
        name, _, rest = line.partition(":")
        name = name.strip()
        rest = rest.strip()

        if rest.startswith("{"):
            if not rest.endswith("}"):
                raise CachePinError(
                    f"{source}: Fehlende schließende Klammer: {line}")
            inner = rest[1:-1]
            for pair in inner.split(";"):
                pair = pair.strip()
                if not pair:
                    continue
                if "=" not in pair:
                    raise CachePinError(
                        f"{source}: Ungültiger Parameter '{pair}'")
                k, v = pair.split("=", 1)
                params[k.strip()] = v.strip().strip('"').strip("'")
        else:
            if "=" not in rest:
                raise CachePinError(
                    f"{source}: Ungültiger Parameter '{rest}'")
            k, v = rest.split("=", 1)
            params[k.strip()] = v.strip().strip('"').strip("'")

    if not name:
        raise CachePinError(f"{source}: Leerer Paketname in: {line}")

    for k, v in PARAM_DEFAULTS.items():
        params.setdefault(k, v)

    return ("package", (name, params))


def load_file(path, seen, base_dir=None):
    """
    Lädt eine Manifest-Datei und expandiert Includes inline.
    seen: globales Set absoluter Pfade → zweiter Auftritt ist Fehler.
    """
    p = Path(path)
    if not p.is_absolute():
        p = (Path(base_dir) / p) if base_dir else p
    abs_path = p.resolve()

    if abs_path in seen:
        raise CachePinError(f"Doppelter/zirkulärer Include: {abs_path}")
    seen.add(abs_path)

    if not abs_path.is_file():
        raise CachePinError(f"Manifest nicht gefunden: {abs_path}")

    entries = []
    for lineno, raw in enumerate(abs_path.read_text().splitlines(), 1):
        kind, payload = parse_line(raw, source=f"{abs_path}:{lineno}")
        if kind == "empty":
            continue
        if kind == "include":
            entries.extend(load_file(payload, seen, base_dir=abs_path.parent))
        elif kind == "package":
            entries.append(payload)
    return entries


def merge(entry_lists):
    """Liste von (name, params)-Listen → dict. Letzter gewinnt."""
    result = {}
    for entries in entry_lists:
        for name, params in entries:
            result[name] = params
    return result


def resolve_expr(name):
    """
    Paket-Name → Nix-Ausdruck.
    - /nix/store/... → unverändert
    - enthält "." oder "#" → voller Ausdruck
    - sonst → nixosConfigurations.default.pkgs.<name>.outPath
    """
    name = name.strip()
    if name.startswith("/nix/store/"):
        return name
    if "." in name or "#" in name:
        return name
    return f"nixosConfigurations.default.pkgs.{name}.outPath"

# modules/features/zram-swap.nix
{ config, lib, pkgs, ... }:

let
  cfg = config.mySystem.zramSwap;
in
{
  options.mySystem.zramSwap = {
    enable = lib.mkOption {
      type = lib.types.bool;
      default = false;
      description = ''
        Aktiviert zram-basierten Swap.
        zram erstellt ein komprimiertes Block-Device im RAM, das als
        zusätzlicher Swap-Speicher dient. Es wird nur dann genutzt,
        wenn der physische RAM knapp wird, und schont so die SSD.
      '';
    };

    algorithm = lib.mkOption {
      type = lib.types.enum [ "lzo" "lz4" "lz4hc" "zstd" "deflate" "842" ];
      default = "zstd";
      description = ''
        Der Komprimierungsalgorithmus für zram.

        - zstd: Beste Kompromiss aus Kompressionsrate und Geschwindigkeit (Empfohlen).
        - lz4:  Sehr schnell, aber geringere Kompressionsrate. Gut für reaktionsschnelle Systeme.
        - lzo:  Gute Kompression, aber langsamer als lz4.
        - Weitere: lz4hc (höhere Kompression, langsamer), deflate, 842.
      '';
      example = "lz4";
    };

    memoryPercent = lib.mkOption {
      type = lib.types.int;
      default = 50;
      description = ''
        Die maximale Menge an Speicher (in Prozent des Gesamt-RAMs),
        die das zram-Gerät belegen darf.
        Hinweis: Dies ist die Größe *vor* der Komprimierung.
        Bei 16 GB RAM und 50% können bis zu 8 GB unkomprimierte Daten
        im zram-Gerät liegen, die physisch weniger Platz einnehmen.
      '';
      example = 30;
    };

    priority = lib.mkOption {
      type = lib.types.int;
      default = 100;
      description = ''
        Die Priorität des zram-Swap-Geräts.
        Der Kernel nutzt Swap-Geräte mit höherer Priorität zuerst.
        Dieser Wert sollte **höher** sein als die Priorität deiner
        SSD-Swap-Partition (üblich sind hier -1 oder -2), damit
        zram zuerst gefüllt wird und die SSD nur als letzter Ausweg dient.
      '';
      example = 200;
    };
  };

  config = lib.mkIf cfg.enable {
    zramSwap = {
      enable = true;
      inherit (cfg) algorithm memoryPercent priority;
    };

    # Explizite Warnung, falls die Priorität nicht höher ist als die der SSD.
    warnings = lib.optionals (cfg.priority <= 0) [
      "mySystem.zramSwap.priority ist auf ${toString cfg.priority} gesetzt. "
      "Dies ist möglicherweise niedriger als die Priorität deiner SSD-Swap-Partition. "
      "Der Kernel könnte dann die SSD anstelle von zram nutzen. "
      "Ein Wert über 0 (z.B. 100) wird empfohlen."
    ];
  };
}

