      default = false;
      description = "Enable Steam, Proton-GE, and GameMode.";
    };
  };

  # ==========================================
  # UMSETZUNG (nur wenn aktiviert)
  # ==========================================
  config = lib.mkIf cfg.enable {

    # ==========================================
    # UNFREIE PAKETE FÜR STEAM
    # ==========================================
    # "steam" als Präfix erlaubt alles, was mit "steam" beginnt:
    #   steam, steam-original, steam-unwrapped, steamcmd, steam-run, ...
    #
    # Wird in die gemeinsame Option gemerged. Spätere Launcher
    # (lutris, heroic) können weitere Präfixe beitragen.
    # ==========================================
    mySystem.games.allowedUnfreePrefixes = [ "steam" ];

    programs.steam = {
      enable = true;

      # Proton-GE deklarativ als Kompatibilitätstool bereitstellen
      extraCompatPackages = with pkgs; [ proton-ge-bin ];

      # Firewall für Steam Remote Play öffnen
      remotePlay.openFirewall = true;

      # ==========================================
      # ZUSÄTZLICHE LAUFZEIT-PAKETE FÜR STEAM
      # [ACHTUNG: ALLES NUR INTERN IN DER STEAM-UMGEBUNG ERREICHBAR]
      # ==========================================
      package = pkgs.steam.override {
        extraPkgs = pkgs': with pkgs'; [
          # 1. GameMode & Gamescope (für Startoptionen wie
          #    "gamemoderun gamescope ... -- %command%")
          gamemode
          gamescope

          # 2. Wichtige Multimedia-Bibliotheken für Video-Dekodierung & Audio
          ffmpeg
          libvorbis
          libpulseaudio

          # 3. Grundlegende X11-Bibliotheken
          libxcursor
          libxi
          libxinerama
          libxscrnsaver

          # 4. Mauszeiger-Fix
          #    Steam läuft in einem FHS-Container und hat sonst keinen
          #    Zugriff auf das Breeze-Cursor-Theme des Hosts.
          kdePackages.breeze
        ];
      };
    };

    # ==========================================
    # ZUSÄTZLICHE TOOLS (Steam-spezifisch)
    # ==========================================
    environment.systemPackages = with pkgs; [
      protonup-qt   # GUI zum Verwalten von Proton-GE-Versionen
      pulseaudio    # stellt "pactl" bereit (Steam nutzt es für Lautstärke)
      fontconfig    # saubere Font-Konfiguration in der Steam-Umgebung
    ];

    # ==========================================
    # LOCALE-FIX FÜR STEAM
    # ==========================================
    # XOpenIM() in Steam braucht LC_CTYPE; sonst hakt die Anmeldung/GUI.
    # Wird nur gesetzt, wenn Steam aktiv ist (Modul bleibt autark).
    # ==========================================
    i18n.extraLocaleSettings.LC_CTYPE = "en_US.UTF-8";
  };
}

# /etc/nixos/Eco-System/modules/userland/nixos_ide.nix
{ config, pkgs, lib, ... }:

let
  cfg = config.mySystem.ide;

  # rsync-Argumente aus der exclude-Liste bauen.
  # escapeShellArg, damit Pfade mit Sonderzeichen nicht brechen.
  rsyncExcludes = lib.concatMapStringsSep " "
    (e: "--exclude=${lib.escapeShellArg e}")
    cfg.exclude;
in
{
  options.mySystem.ide = {
    enable = lib.mkOption {
      type = lib.types.bool;
      default = false;
      description = "Enable IDE setup (Kate + Git + Nix-LSP).";
    };
    repoUrl = lib.mkOption {
      type = lib.types.str;
      default = "https://github.com/deinuser/Eco-System.git";
      description = "Git repository URL for cloning (SSH or HTTPS).";
    };
    repoPath = lib.mkOption {
      type = lib.types.str;
      default = "/home/luisek03/Projekte/Eco-System";
      description = "Pfad zum Eco-System-Repo (Projekt-Root, nicht OS-Root).";
    };
    userName = lib.mkOption {
      type = lib.types.str;
      default = "luisek03";
      description = "Username for the home directory path.";
    };
    exclude = lib.mkOption {
      type = lib.types.listOf lib.types.str;
      default = [
        # Host-spezifisch — /etc/nixos darf diese NICHT überschreiben
        "host-config.nix"
        "hardware-configuration.nix"

        # flake.lock: /etc/nixos ist die "lebende" Instanz (eco-upgrade
        # aktualisiert sie dort). Repo-lock dient nur als Bootstrap.
        "flake.lock"

        # Git & Build-Artefakte
        ".git"
        ".gitignore"
        "result"
        "result-*"
        "*.drv"

        # DOCS musst jz nicht unbedingt in /etc/nixos
        # es würde aber auch nicht schaden da nicht aktiviert wird.
        "docs"
        "README.md"

        # Editor-Kram
        "*.swp"
        "*.kate-swp"
        "*~"
        ".DS_Store"
        ".directory"
      ];
      description = "Files to exclude from rsync when deploying to /etc/nixos.";
    };
  };

  config = lib.mkIf cfg.enable {

    environment.systemPackages = with pkgs; [
      nixd
      git
      lazygit
      gh

      kdePackages.kate
    ];

    # ==========================================
    # WORKFLOW-ALIASES
    # ==========================================
    environment.shellAliases = {
      eco        = "cd ${cfg.repoPath}";
      eco-edit   = "current_dir=$(pwd) && cd ${cfg.repoPath} && kate . && cd $current_dir";
      eco-status = "cd ${cfg.repoPath} && git status";
      eco-commit = "cd ${cfg.repoPath} && git add . && git commit -m \"Update $(date +'%Y-%m-%d %H:%M')\"";
      eco-push   = "cd ${cfg.repoPath} && git push";
      eco-pull   = ''
        cd ${cfg.repoPath}
        if ! git diff-index --quiet HEAD --; then
          echo "⚠️  Uncommittete Änderungen vorhanden – bitte erst committen!"
          git status --short
          exit 1
        fi
        git pull --rebase
      '';
      eco-log    = "cd ${cfg.repoPath} && git log --oneline --graph --all";

      # ------------------------------------------
      # DEPLOY (Flakes, Build aus /etc/nixos)
      # ------------------------------------------
      deploy-dry = ''
        echo "Copying Eco-System configuration to /etc/nixos (dry-run)..."
        sudo rsync -av --delete ${rsyncExcludes} ${cfg.repoPath}/Eco-System/ /etc/nixos/

        echo "Running nixos-rebuild dry-run (flake)..."
        sudo nixos-rebuild dry-run --flake /etc/nixos
      '';

      deploy = ''
        echo "Copying Eco-System configuration to /etc/nixos..."
        sudo rsync -av --delete ${rsyncExcludes} ${cfg.repoPath}/Eco-System/ /etc/nixos/

        echo "Running nixos-rebuild switch (flake)..."
        sudo nixos-rebuild switch --flake /etc/nixos
      '';

      deploy-copy = "sudo rsync -av --delete ${rsyncExcludes} ${cfg.repoPath}/Eco-System/ /etc/nixos/";
    };
  };
}

# Eco-System/modules/userland/ssh-agent-keepassxc.nix
{ config, lib, pkgs, ... }:

with lib;
let
  cfg = config.services.ssh-agent-keepassxc;
in
{
  options.services.ssh-agent-keepassxc.enable =
    mkEnableOption "SSH-Agent (KeePassXC-kompatibel)";

  config = mkIf cfg.enable {
    programs.ssh.startAgent = true;

    environment.etc."environment.d/ssh-agent.conf" = {
    text = "SSH_AUTH_SOCK=$XDG_RUNTIME_DIR/ssh-agent";
    mode = "0644";
};
  };
}

# /etc/nixos/Eco-System/profile/base/default.nix
# ==========================================
# DISTRO-FUNDAMENT
# ==========================================
# Priorität: lib.mkOverride 1200
# (kleinere Zahl = stärkere Priorität)
#   50  mkForce
#  100  normale Zuweisung
# 1000  mkDefault (profile/luis-eco)
# 1200  ← profile/base (hier)
# 1500  Option-Default
# ==========================================
# Skalare: lib.mkOverride 1200 (überschreibbar durch luis-eco + Host)
# Listen/Attrsets: lib.mkDefault 1000 (merge mit luis-eco + Host)
# ==========================================

{ config, pkgs, lib, ... }:

let
  prio = 1200;   # nur für Skalare
in
{
  imports = [
    ../../modules/system/ops
    ../../modules/system/kernel
    ../../modules/system/zram-swap.nix
  ];

  config = {
    # ==========================================
    # BOOT
    # ==========================================
    boot.loader.systemd-boot.enable      = lib.mkOverride prio true;
    boot.loader.efi.canTouchEfiVariables = lib.mkOverride prio true;
    boot.tmp.useTmpfs                    = lib.mkOverride prio true;
    boot.tmp.cleanOnBoot                 = lib.mkOverride prio true;
    boot.supportedFilesystems            = [ "ntfs3" ];

    # ==========================================
    # NETZWERK (Default — Host überschreibt Hostname)
    # ==========================================
    networking.hostName              = lib.mkOverride prio "nixos";
    networking.networkmanager.enable = lib.mkOverride prio true;

    # ==========================================
    # SSH SERVER
    # ==========================================
    services.openssh = {
      enable                                = lib.mkOverride prio true;
      settings.PasswordAuthentication       = lib.mkOverride prio false;
      settings.KbdInteractiveAuthentication = lib.mkOverride prio false;
      settings.PermitRootLogin              = lib.mkOverride prio "no";
    };

    # ==========================================
    # GRAFIK / DESKTOP (Plasma)
    # ==========================================
    services.xserver.enable                = lib.mkOverride prio true;
    services.displayManager.sddm.enable    = lib.mkOverride prio true;
    services.desktopManager.plasma6.enable = lib.mkOverride prio true;

    # ==========================================
    # DRUCKEN
    # ==========================================
    services.printing.enable = lib.mkOverride prio true;

    # ==========================================
    # SOUND (PipeWire)
    # ==========================================
    services.pulseaudio.enable = lib.mkOverride prio false;
    security.rtkit.enable      = lib.mkOverride prio true;
    services.pipewire = {
      enable            = lib.mkOverride prio true;
      alsa.enable       = lib.mkOverride prio true;
      alsa.support32Bit = lib.mkOverride prio true;
      pulse.enable      = lib.mkOverride prio true;
    };

    # ==========================================
    # LOCALE-DEFAULTS (distro = English — luis-eco überschreibt)
    # ==========================================
    time.timeZone      = lib.mkOverride prio "UTC";
    i18n.defaultLocale = lib.mkOverride prio "en_US.UTF-8";
    i18n.extraLocaleSettings = lib.mkOverride prio {
      LC_CTYPE = "en_US.UTF-8";   # Kompatibilität für XOpenIM etc.
    };

    # ==========================================
    # TASTATUR-DEFAULT (US — luis-eco überschreibt)
    # ==========================================
    console.keyMap               = lib.mkOverride prio "us";
    services.xserver.xkb.layout  = lib.mkOverride prio "us";
    services.xserver.xkb.variant = lib.mkOverride prio "";

    # ==========================================
    # ZRAM AKTIVIERUNG / RAM KOMPREMIERUNG
    # ==========================================

    mySystem.zramSwap = {
        enable = lib.mkOverride prio true;
        algorithm = lib.mkOverride prio "lz4";    # Der Standard, guter Kompromiss ggfs auf lz4 wechseln
        memoryPercent = lib.mkOverride prio 50;    # Maximal 50% des RAMs für zram
        priority = lib.mkOverride prio 100;        # Höher als die SSD-Swap-Priorität (z.B. -1)
    };


    # ==========================================
    # NIX SETTINGS
    # ==========================================
    # Kritische Infrastruktur: Flakes MÜSSEN funktionieren.
    # mkForce auf genau diesen Key — kann von nichts überstimmt werden.
    #
    # Restliche Defaults — mergebar mit Profilen und Host.
    # lib.mkMerge führt beide Definitionen in EINEM nix.settings-Block zusammen.
    # Caches — als Beitrag zur mySystem.caches-Option
    mySystem.caches.substituters = [
      "https://cache.nixos.org"
      "https://nyx-cache.chaotic.cx"
      "https://nix-community.cachix.org"
      "https://mic92.cachix.org"
    ];

    mySystem.caches.trustedKeys = [
      "cache.nixos.org-1:6NCHdD59X431o0gWypbMrAURkbJ16ZPMQFGspcDShjY="
      "nix-community.cachix.org-1:mB9FSh9qf2dCimDSUo8Zy7bkq5CX+/rkCWyvRCYg3Fs="
      "nyx-cache.chaotic.cx:dJxTrgMC3V3cFfyIiBQDQorG6k1LsqurH/srpMSq7qk="
      "mic92.cachix.org-1:gi8IhgiT3CYZnJsaW7fxznzTkMUOn1RY4GmXdT/nXYQ="
    ];

    # Rest von nix.settings bleibt wie gehabt
    # (experimental-features, accept-flake-config, max-jobs, …)
    nix.settings = lib.mkMerge [
      { experimental-features = lib.mkForce [ "nix-command" "flakes" ]; }
      (lib.mkDefault {
        accept-flake-config   = true;
        max-jobs              = 4;
        cores                 = 0;
        connect-timeout       = 10;
        download-attempts     = 3;
        max-substitution-jobs = 32;
        http-connections      = 32;
      })
    ];

    nix.nixPath        = lib.mkOverride prio [ "nixpkgs=flake:nixpkgs" ];
    nix.channel.enable = lib.mkOverride prio false;

    # ==========================================
    # DOKUMENTATION
    # ==========================================
    documentation.enable       = lib.mkOverride prio false;
    documentation.nixos.enable = lib.mkOverride prio false;

    # ==========================================
    # BASISPACKETE (KDE / Essentials)
    # ==========================================
    # mkDefault → mergt mit luis-eco + Host.
    environment.systemPackages = with pkgs; [
      git
      nano

      # KDE / Plasma-Werkzeuge
      kdePackages.dolphin
      kdePackages.kio
      kdePackages.kio-fuse
      kdePackages.kio-extras
      kdePackages.kdenetwork-filesharing
      kdePackages.kfind
      kdePackages.partitionmanager
      kdePackages.bluedevil

      ];

    # ==========================================
    # BASIS-ALIASE (sinnvolle Distro-Defaults)
    # ==========================================
    # mkDefault → mergt mit luis-eco + Host.
    environment.shellAliases = {
      ll        = "ls -al --color=auto";
      cls       = "clear";
      watch     = "watch -p";
      cp        = "cp --reflink=auto";
      fastfetch = "nix-shell -p fastfetch --run fastfetch";
    };
  };
}

